-- Reguläre TFB-Partnerleisten. Bestehenden BMW-Eintrag und Splash-Einstellungen bewahren.
DELETE FROM tfb_partner_payments WHERE partner_id IN ('5-elemente','a-s-creation','aldi-sud','aok','bpw','bsv-bielstein','bubenzer-baufachzentrum','coca-cola','die-finanzmaschine-r-kamper','fahrzeugpflege-wiehl','faulenbach-schmiedetechnik','gro-bestattungen','intersport','jagenberg','lang-raum-idee','muller-textil-group','oberberg-apotheke','penz','piccola-italia','sarstedt','schwalbe','seitz','sportpark-am-see','wiehl-apotheke','zappo-apotheke');
ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,logo_data=NULL,revision=tfb_partners.revision+1,updated_at=excluded.updated_at
WHERE tfb_partners.id<>'bmw-kaltenbach-gruppe';
UPDATE tfb_partners SET payload=json_remove(payload,'$.sample','$.status','$.note'),revision=revision+1 WHERE id='bmw-kaltenbach-gruppe';
DELETE FROM tfb_partners WHERE id IN ('5-elemente','a-s-creation','aldi-sud','aok','bpw','bsv-bielstein','bubenzer-baufachzentrum','coca-cola','die-finanzmaschine-r-kamper','fahrzeugpflege-wiehl','faulenbach-schmiedetechnik','gro-bestattungen','intersport','jagenberg','lang-raum-idee','muller-textil-group','oberberg-apotheke','penz','piccola-italia','sarstedt','schwalbe','seitz','sportpark-am-see','wiehl-apotheke','zappo-apotheke');
